    shop_hol_not_now: "今はしない",
    faq_a_shop_delivery: "買い物リストでトラックをタップし、宅配に入っているもの（最初は全部選択済み）、届く日（今日・明日・別の日）、時間帯（午前・午後・夕方、または自分で時間を決める「その他…」）を選びます。それらの項目は、日付と時間帯つきで、リストの上の「配送中」カードに移ります。その日になると、わたしの一日に「宅配は届きましたか？」が表示されます（カードにも「届いた？」があります）。全部届いたら「また買う」に移ります。足りないものがあれば、届かなかったものをタップすると、すぐリストに戻ります。",
    faq_a_shop_departments: "リストはスーパーの売り場ごとに自動で並びます（青果、パン、乳製品・卵、肉・魚、常備品、冷凍食品、飲み物、お菓子、掃除、ケア用品、ベビー、ペット）。だから売り場を順番に回れます。売り場は項目の名前から判断されます。違う場所に入ったときは、項目をタップして売り場を選ぶか、「その他…」を選んで自分で入力してください。",
    faq_a_shop_share_qty: "はい。各項目の横の + で1つ増え（×2、×3…）、− で1つ減ります。買い物リストの上にある共有ボタンで、売り場ごとにきれいに並んだリスト全体を WhatsApp、メール、またはコピーで送れます。",
    faq_a_shop_two_buttons: "どちらも「買った」という意味です。✕ は一度だけ買うもの用で、リストから消えます（間違えたときのために 🗑️ アーカイブに残ります）。↺ は何度も買うもの用で、リストから消えて「また買う」で待っています。リストの一番下、ゴミ箱の横にある小さな ↺ ボタンで開き、そこを一度タップすると項目がリストに戻ります。その中の「編集」から、項目を外せます。項目を追加するときは、以前買ったものが候補として出てきます。すでにリストにあるものは、2行目が増えずに ×2 になります。",
