    faq_a_weekly_table: "カレンダー表示の月間概要の横に、週間表があります。最初は折りたたまれていて、タイトルをタップすると開きます。週の毎日の予定とタスク、繰り返しの週間タスクが時間順に表示されます。‹ › で週を切り替え、項目をタップすると編集画面が開きます。",
