    nm_demo_title: "入れ替えのしくみ",
    faq_a_new_me_challenge_journal: "チャレンジが終わると（ビッグチャレンジ、ミニチャレンジ、今週のチャレンジのどれでも）、お祝いの画面に「📝 どうでしたか？」ボタンが出ます。押すとチャレンジ日記のページが開きます：どう感じたか（5つの顔）、何が助けになったか、何が大変だったか、ここから何を持っていくか。どれも必須ではなく、あとで書くこともできます。日記は魔法のリュックの中のダイヤモンドです：終えたチャレンジが日付と書いた内容といっしょに、新しい順に並びます。ひとつタップすると、読む・編集する・共有することができます（共有されるのはページに書かれた内容だけです）。終えたチャレンジには、バッジの「達成したチャレンジ」にメダルもつきます。チャレンジ日記は、ふだんの日記とは別のものです。",
