    nm_swap_time: "時間",
    faq_a_ai_reminder_in_text: "はい。タスクと一緒に書くだけです(例：「明日17:00に荷物を受け取る、1時間前にリマインダー」)。リマインダーはタスク自体に保存されます。1時間前、30分前、前日などが使え、時間を書かない「リマインドして」は10分前になります。テキストに書いたリマインダーは、同じ画面のリマインダー欄より優先されます。",
    faq_q_ai_reminder_in_text: "同じ依頼の中で、AIアシスタントにリマインダーも頼めますか？",
    myday_meals_all_done: "今日の食事はすべてチェック済み 🍽️",
    nm_tour_week_text: "1週間の小さなチャレンジ。毎日✓ – 最後にカギ。",
    books_home_chip: "{title} · {page}ページ",
    books_home_of: "/ 全{total}ページ",
    books_home_off_toast: "本をホーム画面から外しました",
    books_home_on_toast: "本をホーム画面に表示しました 📖",
    books_home_pin: "ホーム画面に表示",
    books_home_q: "いま何ページ目？",
    books_home_save: "保存",
    faq_a_books_home_chip: "はい。読書コーナーで、読んでいる本のカードにある 📌 ホーム画面に表示をタップします。ホーム画面のあいさつの下に、本とページが書かれた小さなボタンが現れます。タップして新しいページ番号を入力し、保存すると、進み具合が記録されます（読書コーナーにも反映されます）。もう一度 📌 をタップすると外れます。複数の本を一緒に表示でき（1冊ごとにボタンがひとつ）、すべての端末で同じです。",
    faq_a_new_me_week_challenge: "自分で選ぶ、1週間の小さなチャレンジです。廊下に大きなカードがあり、「今週は何に取り組みたいですか？」と聞かれます。タップして、分野（自分と向き合う、人とのかかわり、学ぶ・成長する、心の落ち着き、小さな勇気の一歩、暮らしと習慣）とチャレンジを選び、いつ始めるかを決めましょう。同じチャレンジはチャレンジ画面の 🌱 自己成長にもあります。毎日カードに✓をつけ（週に1日はフリーデー）、終えた週ごとにひみつの世界の新しいカギがもらえます。「1日2ページ読む」は、読書コーナーに記録したページから自動でチェックされます。週が終わったら、📌 毎日のタスクとして続けるを選ぶと、決めた時間でマイルーティンに追加され、毎日✓がつきます。今週のチャレンジは一度に1つだけで、ビッグチャレンジやミニチャレンジは並行して続けられます。",
    faq_a_room_genie: "海の見えるポーチで、アラジンのランプをタップすると森の精が現れ、会話が始まります。あなたの願いは何か（人生で何を変えたいか）、叶ったときどんな気持ちになるか、道のりで何が難しいか、今の状況をどうよいものに変えられるか。そのあと、だいたいどのくらいかかるか、小さな最初の一歩とあと2つ、そして難しくなったときのための「もし…なら、…する」を聞かれます。最後に願い全体が一歩ずつ表示され、マイ目標の目標にする（ステップは道のチェックポイントになり、選んだ期間に合わせた日付がつきます。そこではすべて変更できます）か、日記に保存できます。そのあと森の精はお別れを告げます。どちらかを選ばない限り、何も保存されません。2回目からは、森の精がまず人生でほかに変えたいことがあるかをたずねます。「はい」なら同じ会話が始まり、「今はまだ」なら、すでに決めた目標をかなえようというメッセージが表示されます。森の精が現れるのは1日1回です。願いを保存すると（または「今はまだ」を選ぶと）、明日まで休みます。質問は、願いを計画に変えるよく知られた方法に沿っています。願い、結果、障害、そして計画です。",
    faq_q_books_home_chip: "ホーム画面に本とページを表示できますか？",
