    nm_me_on_screen: "表示中",
    faq_a_new_me_game: "New Meでは、ゲームのボタンはいつも同じ場所にあります。廊下でも、ひみつの部屋でも、森のどこにいても同じで、変わるのは真ん中の絵だけです。上には：歩みの何日目か、カギ、連続日数、今日のエネルギー（プランのうちどれだけ食べたか）、その下に次のミッション – その時間の次の食事（タップで開きます。✓ 食べた もそこにあります）。横には：1日全体、チャレンジとわたしの歩み、そのとなりに今週のチャレンジ（7日間と、今日の✓）。下には：魔法のリュック（New Meのすべて – ワールドマップ、わたしの歩み、買い物リスト、バッジ、チャレンジ日記、サイズ測定、経過写真、月間カレンダー、1日の表、リマインダー、献立PDF、設定。専用の画面として開きます）があります。リュックの最初にあるワールドマップには森のすべての場所があり、場所をタップするとそこへ行けます。閉じている場所には、必要なカギの数が表示されます。Meは森の小道にいるあなたのキャラクターです。Me1から始まり、いくつかチャレンジをこなすと（カギ4本）Me2に、終わりが近づくと（カギ9本）Me3に成長し、その変身を目の前で見られます。Meをタップすると、すべての段階が見られます。すでに到達したキャラクターはもう一度選べるので、前のキャラクターに戻すこともできます。Meは浮かんでいて、指やマウスでドラッグすると、触れた入り口が開きます（カギがかかった入り口には足りないカギの数が表示されます）。Meはどの部屋や場所にもついてきて、置いたところで浮かんでいます。好きな場所へドラッグでき、足もとの光る輪をドラッグすると、ぐるりと一回転させられます。Meは進む方向を向きます（パソコンでは矢印キーで移動、QとEで回転）。廊下では、上部バーの下にある小さな🏠でホーム画面に戻れます。どの部屋や場所でも、同じ角のボタンで廊下に戻れます。",
    faq_q_new_me_game: "ゲームのボタン、ワールドマップ、Meはどんな仕組みですか？",
