    room_magic_song_rec3: "滝のチャイム",
    faq_a_new_me_menu_build: "まず質問票で、どの食事をいつとるか（食事2回 + 間食、食事2回 + 軽い夕食、またはその両方）、夜に何かとるか（食べるか飲むか、何を、何時に）を聞きます。「食事2回 + 間食」の場合、食事は昼食（11:30）と夕食（19:00）で、間食は16:00です。次に、それらの食事の候補がすべて表示されます。各食事で最大2つのお気に入りを選ぶと、メニューには「これ または あれ」と表示されます。一部の候補（ピタとスプレッド、コーンフレークと牛乳、軽いもの）では、好きなものをそれぞれ決まった量で3つまで選べ、メニューには「これ または あれ または それ」と表示されます。カロリーは選んだものに合わせて変わります。コーヒーと飲み物も同じしくみです。どの選択も調整されるので、1日の合計はちょうど1,300または1,500になります。いつでも変更するには：⚙️ 設定 → 🍽️ 献立を作成、または食事のカードの「好きなものを3つまで選ぶ」へ。",
