    faq_a_myday_water_toggle: "はい。「わたしの一日」の水のコップ（＋でもう1杯）は最初から表示されています。非表示にするには、設定 > パーソナライズとカレンダーで「『わたしの一日』に水を表示」をオフにします。何も削除されません。水分補給の記録はそのまま使え、オンに戻すとコップがまた表示されます。",
    faq_q_myday_water_toggle: "「わたしの一日」の水を非表示にできますか？",
    myday_water_toggle_label: "「わたしの一日」に水を表示",
    faq_a_routine_newme_sync: "New Meがあれば、「マイルーティン」の⚙️に「New Meと同期」のスイッチがあります。オン（初期設定）のときは、今日のNew Meの食事が、隠したルーティンの食事の代わりに「わたしの一日」と「マイルーティン」に表示されます。オフにすると、New Meの食事はどちらからも外れ、ルーティンは元どおりに戻ります。何も削除されません。もう一度オンにするとすべて戻り、ルーティンのどの食事を隠すかを聞かれます。",
