    theme_name_watercolor_wash: "水彩",
    faq_a_food_list_languages: "内蔵の食品リストは、イスラエルの料理とそのヘブライ語名から作られました。ヘブライ語以外の言語では各食品が英語名で表示され、検索ではリストが知っている英語名すべてで見つかります（例：'broth' で Clear soup）。ヘブライ語名しかない食品は表示されません。リストにないものは、自分の言葉でそのまま書けば大丈夫です。AIによる推定はどの言語でも使えます。",
    faq_q_food_list_languages: "食品リストが英語名で表示され、品目も少ないのはなぜですか？",
    settings_copyright_line: "© 2026 無断転載を禁じます。アプリ開発：eden zabari",
    workout_ready_replace_btn: "置き換える",
    faq_a_sport_workout_ai: "「わたしのワークアウト」→ ⋯ →「AIでプラン」（表が空のときは、おすすめプランの横のタイルからも）。週に何回、いつ、場所、レベル、目標をタップで答え（ほとんどに「その他」もあります）、必要なら「ひざが弱い」「夏までに5km走りたい」などを1行で書き添えます。AIが1週間分を組み立てます：ワークアウトの種類、曜日、時間、長さ、強度、エクササイズ、休息日。保存の前にプレビューが出るので、「表に入れる」（今の表の代わりに、または追加で）、「別の提案」（3回まで）、「答えを変える」から選べます。プランはあえて控えめで、痛みやけがについて書くと、やさしい内容と専門家への相談をすすめる一文が付きます。スケジュールやルーティンのAIと同じ回数枠を使います：無料で5回、プレミアムなら月60回。",
