    workout_ai_working: "プランを作成中…",
    faq_a_sport_workout_jar: "ワークアウトの種類ごとに色の違う星があります。ランニングはピンク、ウォーキングは緑、水泳は青などです。今週記録したワークアウト（表からでも単独でも）は、その星が「わたしのワークアウト」の上にあるびんに入り、びんは週の目標に向かって満ちていきます（タップすると目標を変えられます）。目標に届くとびんが光ります。横の小さなびんは、何週連続でびんを満たしたかを数えます。",
    faq_q_sport_workout_jar: "「わたしのワークアウト」のカラフルな星とびんは何ですか？",
    faq_a_sport_workout_gcal: "はい。⋯ → Google カレンダーから（設定で Google カレンダーを接続したあと）。時間が決まっているワークアウトは、その曜日に毎週くり返す予定になり、アプリでの変更も反映されます。リマインダーはアプリからだけ届くので Google 側では追加されず、アプリ内でワークアウトが二重に表示されることもありません。もう一度タップすると、Google カレンダーからワークアウトだけが削除されます。",
    faq_q_sport_workout_gcal: "ワークアウトを Google カレンダーに表示できますか？",
    workout_gcal_btn: "Google カレンダー",
    workout_gcal_error: "Google カレンダーを更新できませんでした。次の変更時にもう一度試します",
    workout_gcal_not_connected: "先に設定で Google カレンダーを接続してください",
    workout_gcal_off_toast: "ワークアウトを Google カレンダーから削除しました",
    workout_gcal_on_toast: "ワークアウトを Google カレンダーに追加しました",
    faq_a_sport_workout_reminder: "はい。ワークアウトの「リマインダー」で、10分前・30分前・1時間前、または任意の時間を選べます（ワークアウトに時間の設定が必要です）。ほかのリマインダーと同じ音で、1回だけ1か所に届きます。アプリが開いていればアプリに、そうでなければスマホに。「完了」でワークアウトが履歴に記録され、「まだ」なら5分後にもう一度お知らせします。",
    faq_q_sport_workout_reminder: "ワークアウトの前にリマインダーを受け取れますか？",
    workout_reminder_30min: "30分前",
    workout_reminder_label: "リマインダー",
    workout_reminder_need_time: "リマインダーを受け取るには時間を設定してください",
    faq_a_sport_workout_share: "⋯ → シェアで、1週間がテーマの色のガラス風画像になり、アプリへのさりげないリンクが付きます（スマホではそのまま共有メニューへ、パソコンでは画像が保存されます）。⋯ → 印刷用PDFでは1週間全体のすっきりしたページが開き、各ワークアウトとエクササイズの横にチェック欄があります。「PDFとして保存」を選ぶか印刷してください。プランは設定のデータレポートのスポーツの項目にも載ります。",
    faq_q_sport_workout_share: "1週間のワークアウトをシェア・印刷するには？",
    share_image_saved: "画像を保存しました。添付して送れます",
    share_save_image: "画像を保存",
    workout_pdf_btn: "印刷用PDF",
    workout_share_btn: "シェア",
    faq_a_sport_workout_board: "⋯ → 週ボードでは曜日ごとに列が並びます。ワークアウトを別の曜日へドラッグしてください（スマホでは先に長押し）。ワークアウトの「マイルーティンにも追加」をオンにすると、その時間と曜日でルーティンに入り、変更はどちらからでも同期されます。マイルーティンの項目からは「わたしのワークアウトに追加」で逆の操作ができます。どちらかで ✓ を付けると両方に反映され、「わたしの一日」では水の横のチップに1回だけ表示されます。",
    faq_q_sport_workout_board: "ワークアウトを別の曜日に移したり、マイルーティンとつなげたりするには？",
