    workout_view_timeline: "タイムライン",
    faq_a_sport_workout_plan: "「ワークアウト記録」の「わたしのワークアウト」で ＋ ワークアウト – 種類、曜日、時間、長さ、強度、場所（「その他」も）を選べます。筋トレ・ファンクショナル・水泳にはエクササイズのリストを付けられ、「休息」は休息日の印です。おすすめプランから始めることもできます。今日のワークアウトは大きく表示され、その下に1週間全体が並びます。✓ を押すと強度と一緒にワークアウト履歴に記録されます。⋯ で週の目標（回数または分数）を決められます。ワークアウトをするたびに、その星がびんに入ります。",
    faq_a_sport_workout_today: "「わたしの一日」の水の横にある小さなチップに、今日のワークアウトが表示されます。タップすると詳細と ✓・▶ が開きます。▶ でタイマーが始まり、ホーム画面のチップでも動き続けます。「終了」を押すと実際の時間で記録されます。New Me のチャレンジ「体を動かす2週間」が進行中なら、記録したワークアウトが自動でカウントされます。",
