    faq_a_new_me_magic_themes: "New Me に含まれる、きらきら輝く5つのテーマです：魔法の森、星くず、バラの妖精、魔法のオーロラ、金色の夕暮れ。New Me の中（⚙️ 設定 > カラー）か、設定 > 外観と表示 で選ぶと、きらめく筆が画面をそのテーマで塗っていきます。魔法のテーマではアプリ全体と、タップするたびにきらめきが広がります。いつでも他のテーマに戻せます。",
