    apptour_m_presets_text: "保存した食事をひとまとめに。検索、最近使ったもの、時間帯別――＋で今日に追加できます。",
    apptour_night_text: "🌙でアプリ全体が暗くなり、☀️で昼に戻ります。",
    apptour_noteline_text: "書いて➤をタップするとメモに保存されます。先頭の📝で🛒買い物や🍎保存した食事に切り替わります。",
    apptour_search_text: "メモ、買い物、カレンダー、レシピ、ノート、目標、テーブル、本――ひとつの検索ですべて見つかります。",
    faq_a_new_me_ai_menu: "メニューの前に、質問票でどの食事をいつとるか（食事2回 + 間食、食事2回 + 軽い夕食、またはその両方）、夜に軽く何か食べるか、何時か、食べないもの、コーヒーやお茶の飲み方を聞きます。そのあとAIが各食事に3つの候補を作ります。どれも1日の中でその食事が受け持つ量に合わせてあるので、1日の合計はちょうど1,300または1,500のままです。飲みもののアイデアも作られ、いつもの飲みものとして保存されます。各食事で最大2つのお気に入りを選べます。元のメニューの候補はそのすぐ下にあり、🔄 入れ替え ではあなたのメニューのあとに表示されます。🔄 ほかの候補 で新しいセットを作れます（質問票1回につき3回まで）。答えを変えたり新しいメニューを作ったりするには、いつでも ⚙️ 設定 → ✨ あなたのメニュー（AI）へ。",
