    settings_sub_status_newme: "プレミアムはNew Meに含まれています。",
    room_back_to_shelf: "棚へ",
    faq_a_new_me_day_total: "毎日ちょうどプランどおりになります：食事、日中のコーヒーと飲み物用の約150kcal、そして夜に選んだもの（少しだけ食べるか、飲み物だけ）。夜の分は好きなものを3つまで選べ（たとえばバナナ1本、ヨーグルト、ダークチョコ2かけ、またはハーブティー、ミルクを少し入れた紅茶、ホットミルク）、そのカロリーは食事から差し引かれます。どの選択も自動で調整されます：小さめ・大きめの選択肢、抜いた食事、軽い朝食とそれにつく小さな食事、夜の分――差は各食事の大きさに応じて足したり引いたりされ、各食事の下にいくつ（+か−）と、何を足す・減らすかが表示されます。すでにチェックした食事は記録どおりのままです。質問票では各食事に調整が表示され、小さな枠に食事・飲み物・夜・合計が出ます。その日にほかのものが食べたくなったら？合計を同じカロリーか、それ以下に保ちましょう。",
