    faq_a_book_quotes: "ひみつの部屋の棚（名言）か、読書コーナーの小さな「💬 名言」チップから。どちらも同じリストです。「＋名言」をタップして一節を書き、読書コーナーの本を選ぶか、「✏️ その他」で別のタイトルを入力します。著者は任意です。✏️で編集、🗑️で削除できます。 名言はスワイプでめくるしおりです。上の🎨で写真やカードのウォールに切り替えられます。",
    faq_a_room_wish_jar: "ひみつの部屋の棚には、夢を入れるガラスの瓶があります。いちばん上の段の小さな瓶をタップ（または 棚 > ねがいごとの瓶）して、どんな人生にしたいかを書きましょう。思いきり自由に、正解も不正解もありません。ねがいごとは一枚ずつ紙にたたまれて瓶に落ちます。「紙を一枚引く」でランダムに一枚開き、どの紙も個別に開けます。同じねがいごとを2回目に開いたときから、目標にして小さなステップに分けられます。週に一度、ねがいごとの一枚がそっと現れます。プレッシャーはなく、向かう先を思い出すためだけです。",
