    faq_a_saved_meals_page: "保存した食事には専用のページがあります：栄養と指標 > ⭐ 保存した食事（またはメニューの⭐）。上の検索で名前や材料から食事を探せます。「最近使った食事」には最近追加したものが並び、タブ（朝食・昼食・夕食・スープ…）で時間帯ごとに見られます。「＋今日」を押すと、今日の毎日の食事記録の次の空き枠に追加されます。食事をタップすると編集・削除ができ、上の＋で新しい食事を追加できます。",
