    presets_tab_sweet: "お菓子",
    faq_a_notes_sticky_look: "メモはガラスのカードの短いリストです。メモの上の🎨で、メモ全体の見た目（リスト、上の日付ボタン、メモを書くウィンドウ）を変えられます：ガラス、シンプルなリスト、情報カード、マスキングテープ。ドラッグ中のメモは、自分の見た目と色をそのまま保ちます。テキストをタップすると開き、そこで編集したり、色を変えたり、最後に書いた日時を見たりできます。終わったら○をタップ、×でアーカイブに移動します（リストの下の🗑️から戻せます）。⠿をつかんでドラッグすると、順番の変更、「そのうち」の下への移動、上の日付への移動ができます。 ! はメモを急ぎにします – 小さな「急ぎ」タグがついて、最初の行のほうへそっと上がります。もう一度タップすると外れます。",
    faq_q_notes_sticky_look: "メモを開く・編集する・消すには？",
    note_to_archive_btn: "アーカイブに移動",
    faq_a_routine_clash: "同じ曜日のその時間にすでに項目がある場合、2つの選択肢が出ます。「入れ替える」– 新しい項目がその時間に入り、もとの項目の移動先の時間を選びます（既存の項目を編集しているときは、その項目のもとの時間が提案されるので、2つがそのまま入れ替わります）。「両方」– 2つとも同じ時間に、上下に並んで残ります。曜日が違う場合（たとえば片方が日〜木、もう片方が金曜）は、何も聞かれません。",
    faq_q_routine_clash: "ルーティンで、すでに埋まっている時間に項目を入れるとどうなりますか？",
