    routine_clash_title: "{time}にはすでに「{title}」があります",
    faq_a_new_me_coffee: "今日の献立の下に短いまとめがあり、今日の食事の合計カロリー、コーヒーや飲み物に使える残り、そして選んだコーヒーと飲み物のボタンが表示されます。1回タップで飲み物に追加されます。ボタンの下の「好きなものを3つまで選ぶ」（質問票でも）で、表示するものを選べます：水 / 炭酸水、ハーブティー、ダイエット飲料、ブラック / アメリカーノ（~5）、ミルクを少し入れた紅茶（~25）、お湯で淹れて牛乳か植物性ミルクを100mlまで加えたコーヒー（~50）、軽めのココア、ホットミルク、ふつうのコーヒー / ラテ（~120）。",
    faq_q_new_me_coffee: "コーヒーはどこで追加し、その日の残りはどうやって分かりますか？",
