    faq_a_recipe_examples: "自分のレシピの下に、朝食、サラダ、スープ、主菜、副菜、間食、デザート、ヴィーガン料理のレシピの例があります。それぞれに調理時間、1人前のカロリー、1人前が何グラムかが書かれています。レシピをタップすると開き、「マイレシピに保存」で編集できる自分用のコピーが作られます。カテゴリのチップで絞り込めて、同じチップをもう一度タップするとすべて表示されます。",
    faq_a_recipe_grams: "レシピの中、カロリーの横に「1人前 ≈ Xg」と表示されます。自分のレシピでは、レシピのフォームで「1人前のグラム数」（必要なら調理時間も）を入力します。どちらも任意で、時間はレシピのカラー帯に表示されます。",
