    faq_a_recipe_scan_multi: "はい。「レシピを追加」で📷をタップし、写真を1枚または複数（6枚まで、PDFも可）選びます。それぞれが短いリストに表示されるので、写っている内容を「すべて」「材料」「作り方」から選び、「➕ 写真を追加」でさらに追加できます。最後に「✨ レシピをスキャン」をタップすると、AIが順番どおり、重複なく1つのレシピにまとめます。スキャン1回分として数えます。 AIアシスタントの 📷 写真 から選んだ複数の写真も、ここで開きます。",
