    faq_a_note_written_at: "メモの文字をタップすると開きます。中の文字の下に、最後に書いた日時が正確な日付と時刻で表示されます。更新されるのは文字そのものを変えたときだけで、アーカイブと復元、✓、色、並べ替えでは変わりません。",
