    faq_a_new_me_month: "魔法のリュック →「月間カレンダー」で見られます。各日はチェックした食事の数で色分けされ、‹ › で月を移動でき、カレンダーの下にその月の1日あたりの平均カロリーが表示されます。日付をタップすると、その日にチェックした食事の数と食べたカロリーが表示されます。",
    faq_q_new_me_month: "New Me で過去の月と平均カロリーはどこで見られますか？",
    nm_month_avg: "月の平均：1日{kcal}kcal ・ 記録した日数：{n}",
    nm_month_day_empty: "この日は記録がありません。",
    nm_month_day_line: "チェックした食事：{checks} ・ カロリー：{kcal}",
    nm_extra_line_small: "この食事に{n}kcal（軽めの朝食の分）– たとえば{ideas}",
    faq_a_new_me_small_breakfast: "軽めの朝食（約170kcal）です：スペルト小麦のピタ（100kcalまで）にスプレッドかチーズ、それに野菜も。好きなものを3つまで選べます（たとえばチョコスプレッド小さじ1、ピーナッツバター小さじ1、脂肪分22%までのスライスチーズ1枚）。量が少ないので、別の時間に「もうひとつ小さな食事」がつきます（1時間半後、たとえば11:30 → 13:00。ほかの時間も選べます）：もう1枚ピタとスプレッド、プロテインヨーグルトとフルーツ、ライスケーキとチーズ、シリアルと牛乳、ピタ半分と卵のどれかで、約200kcalまで、専用の✓つきです。それでも残ったカロリーはほかの食事に分けられ、それぞれの食事に追加分が表示されるので、1日の合計はプランどおりのままです。質問票で選ぶことも、🔄 で今日だけ切り替えることもできます（たとえば朝食が遅くなったとき）。",
