    faq_a_ai_icon: "はい。設定 > 外観と表示 で変えられます。初期設定はふんわりバブルで、Premium では浮かぶ脳やロボットも選べます。",
    faq_a_new_me_favorites: "はい。質問票（設定からのやり直しでも）で、各食事に最大2つの選択肢を選べます。1つ目がメニューに表示され、その下に2つ目の「または」の行が出ます。タップすると今日だけそちらに切り替わります。また、朝食を時間内に食べられなかったときは、「⏰ あとで」で今日のあとの時間に移せます。カロリーは変わりません。",
    faq_a_theme_mode: "特別テーマのうち、水彩、オーロラ、バービー、2つのキラキラテーマはダークでいちばんきれいに見えるので、どれかを選ぶとアプリはダークモードに、ほかのテーマ（ロケットも）を選ぶとライトモードに切り替わります。ブラックとダークグレーはダークのままです。あとからいつでも、メニューの 🌙 や設定の「ライトモード」で変えられます。",
    faq_a_water_month: "水の記録で見られます。今日の記録の各項目には追加した時刻が表示され、「月間表」を開くと1か月全体が見られます。各日に飲んだリットル数が表示され（1日の目標に届いた日は ✓）、日付をタップするとその日の記録が時刻つきで表示されます。",
