    dev_sim_panel_title: "PM – あなた専用",
    faq_a_new_me_weight_optional: "いいえ。質問票の現在の体重も目標体重も任意です。あとから体重を記録すると（New Me の「わたしの歩み」の ⚖️ 体重、または体重記録）、最初の記録から進み具合を数えます。",
