    nm_unlock_title: "New Me がオープンしました！",
    room_reveal_star: "屋上の望遠鏡に新しい星が灯りました ✨",
    faq_a_room_records: "レコードプレーヤーは最初から部屋の中、ひじかけ椅子のそばの切り株の上にあります。レコードを選ぶと、ここ数年の大ヒット曲の公式ミュージックビデオがYouTubeで開きます。その下には、この部屋でそのまま流れる静かなメロディーが5曲あります。流れている間はレコードが回り、「⏹ 止める」で音楽が止まります。",
    faq_a_room_roof_gifts: "8本目のカギで現れます。望遠鏡をタップすると、のぞくことができます。夜空がすぐ近くに広がり、ドラッグ（または矢印）で見回せます。終えたチャレンジはそこで星座を描き、チャレンジごとに星がひとつ。星をタップするとどのチャレンジだったかがわかります。小さな宝箱をタップすると開きます（今はまだ空っぽです）。もう一度タップすると閉じます。",
    faq_q_room_records: "ひみつの部屋のレコードプレーヤーには何がありますか？",
