    room_chest_letter: "あなたへの小さな手紙",
    room_chest_letter_1: "道のりの小さな一歩は、どれも本物でした。そのひとつひとつに意味があります。",
    room_chest_letter_2: "自分にやさしくすることは、道の一部。休憩ではありません。",
    room_chest_letter_3: "軽い日もあれば、重い日もあります。どちらの日も向き合うこと、それが本当の強さです。",
