    faq_a_new_me_preview: "はい。New Me のページは、中で起こることを紹介する短い動画から始まります：質問票、廊下のランプ、魔法のリュック、チャレンジ、カギ。その下に、含まれるものすべて、1日の様子、短いQ&Aがあります。",
