    faq_a_new_me_home_btn: "New Me をお持ちなら、ホーム画面の上、集中モードの横にある小さな 💎 で今日のメニューが開きます。今日の食事は「わたしの一日」にもそれぞれ ✓ 付きで表示されます。",
    faq_a_routine_item_days: "はい。マイルーティンで項目をタップし、📅 曜日 で曜日を選びます（たとえば月曜から金曜だけ）。それ以外の日は「わたしの一日」に表示されず、✓ もありません。マイルーティンでは薄く表示され、横に曜日が出ます。✓ のない日が3日続くと項目について尋ねるカードも、その項目の曜日だけを数えます。",
