    room_game_marquee: "道の途中で、立ち止まって楽しもう",
    room_sand_erase_aria: "こすって文字を消す",
    faq_a_home_note_line: "ホーム画面の真ん中の行に書いて ➤（またはEnter）をタップすると、メモに保存されます。行の最初の 📝 をタップすると 🛒 に変わり、書いたものが買い物リストに入ります。もう一度タップすると 🍎：数文字入力すると合う保存した食事が出てきて、タップするとその食事が今日の食事に記録されます。🎤 なら声で言うだけでOKです。",
    faq_a_night_mode: "メニュー ☰ を開いて、上の 🌙 をタップすると、アプリ全体が暗くなります。同じ場所の ☀️ で昼に戻ります。設定の「ライトモード」からも切り替えられます。",
    faq_q_home_note_line: "ホーム画面からクイックメモを書くには？",
    faq_q_night_mode: "ナイトモードにするには？",
    menu_day_mode: "デイモード",
    menu_night_mode: "ナイトモード",
    faq_a_secret_room_yoga: "森の小道の先に光る門があり、その向こうの滝のそばで、森の生きものたち――ルミ、パフィ、ニクシー、スパークレット――が半円になってマットの上に座り、ヨガの先生のフローラは、岩の上にひとつだけあるマットにみんなと向かい合って座っています。フローラをタップすると目を開け、すべてが近づいて、会話がゆっくり、読む時間をとりながら始まります。フローラがみんなの調子をたずね、生きものたちがそれぞれ自分の名前で答えます（どの行の横にも、話している生きものの小さな絵があります）。それからフローラは、身近な人たちといてどんな気持ちかをあなたにたずねます。会話はあなたの答えに合わせて進みます――いい人たち、苦手な人、少しひとりの気持ち。どの道も小さなミッション（そのまま「わたしの一日」に追加できます。何かを書くミッションのときは書く場所があり、魔法の日記に保存されます）と、いっしょに3回呼吸するポーズで終わります。↩ で一歩もどり、✦ で新しい会話を始めます。次のカギで滝が開きます。岩にすわるとすべてが消え、水の音だけが残ります。池をのぞきこむと、水の中から「本当の自分なら、今日なにをする？」という問いが浮かび、答えは「わたしの一日」の小さなタスクになります。やさしいひとときですが、専門家に相談する代わりにはなりません。",
    faq_q_secret_room_yoga: "森のヨガでは何が起きるの？",
