    faq_a_new_me_times: "最初の質問票の中で、またはいつでもNew Meの設定 →「食事の時間」から。ルーティンにすでに食事の時間があれば、そこから取り込まれます。ルーティンの食事を隠して、代わりにNew Meの食事を表示することもできます。なければ、1日の食事の回数（食事2回 + 間食 / 食事2回 + 軽い夕食 / 食事2回 + 間食 + 軽い夕食）とそれぞれの時間を選びます。「食事2回 + 間食」の場合は、昼食11:30、間食16:00、夕食19:00です（どれも変更できます）。この時間が、廊下でも「わたしの一日」でも「マイルーティン」でもリマインダーでも、食事の時間になります。どれを選んでも1日のカロリーは変わりません。抜いた分はほかの食事に分けられます。",
