    faq_a_routine_exact_time: "はい。AIに正確な時刻つきでルーティンを伝えると（例：「16:10 トレード」）、ちょうどの時刻に丸めずそのまま保存されます。ルーティンに書かれたものは、時間の設定でその時間が選ばれていなくても必ずボードに表示されます。何か書かれている時間を外すときは、先に確認が出ます。時間は手動でも変えられます：項目のウィンドウで時間をタップして、時と分を選びます。",
