    routine_daysoff_which: "どの曜日？",
    faq_a_secret_room_diary: "あなただけです。日記のページはアカウントに保存されるので、どの端末でも見られて、ほかの誰にも見えません。日記は、ひみつの部屋の机の上にある魔法の日記からも、音楽コーナーの日記からも開けます。新しいページの下には、たたまれた月のカレンダーがあります：ページがある日には点がつき、日をタップするとその日のページが開きます。そこでページを削除することもできます。日記が開いたら、メインメニューに追加することもできます。日記の中か、New Me の設定のスイッチでどうぞ。",
    faq_a_secret_room_places: "森の門の入り口は、それぞれ専用のカギで開きます。その向こうには：海の見えるポーチ（小さなテーブルの上のアラジンのランプ。タップすると森の精が魔法の霧の中から現れ、くるくる舞って、あなたの願いについての会話を始めます。「ランプの精は何をしてくれますか？」を参照）、ギターと日記（ギターは短く穏やかなメロディーを奏でて自然に止まります。木につるされた3枚のレコードは、それぞれ魔法のようなメロディーを奏でます。もう一度タップすると止まります。切り株の上の日記には書き込めます）、呼吸の部屋（夕暮れの静かな湖：水面に蓮のランタンが浮かんでいます。タップして願いを書くと、願いと一緒に湖のずっと遠くへ流れていきます。魔法の杖で手放したいことを砂に書くと、指でこするまで残ります）、そして森の小道（夜に開き、ランタンをタップすると昼に切り替わります。大きな枝には魔法のブランコが下がっていて、ベンチには座れて、看板をタップすると近くで見られます：チェックできる6つの小さな問いが並んだボード）。カギのかかった入り口には、あといくつカギが必要かが表示されます。小道の先の光る門は滝のそばのヨガへ、そこから滝そのものへと続きます。",
