    dev_weather_preview_label: "プレビュー – あなたのアカウントのみ：",
    faq_a_ai_chat: "吹き出しをタップするとチャットが開きます。やりたいこと（カレンダーに入れること、食べたもの、レシピの写真、新しい表）を選ぶか、そのまま書くだけで、アシスタントが自分で判断します。カレンダーは1回だけ・毎週・毎日から選べます。答えはチャットに届き、そこからほかのことに進んだり、カレンダーや食べたものを開いたりできます。",
    faq_a_new_me_hall: "New Meは魔法の森の門から始まります。森の入り口はどれも、ひとつの場所につながっています。巨大な木の丸い扉はひみつの部屋へ、中が空洞になった丸太は海の見えるポーチへ、きのこの家はギターと日記へ、小さな柳のアーチは呼吸の部屋へ、大きな柳のアーチは森の小道へ。はしごのかかった花のアーチからは、星の屋上が開いたあとにそこへ上れます。カギのかかった入り口には錠前がついています。小道にはあなたのキャラクターMeが浮かんでいて、まわりにはゲームのボタンがあります：次のミッション、今週のチャレンジ、New Meのすべてが入った魔法のリュック、ワールドマップ、ツール。上のカギをタップすると、カギの手に入れ方がわかります。",
    faq_a_new_me_routine_meals: "New Meで食事が決まっていて、マイルーティンにも食事がある場合、New Meは二重に表示されないように、ルーティンの食事を隠して代わりにNew Meの食事を表示するかどうかを尋ねます。するとマイルーティンには、New Meの食事がその時間に💎と✓つきで表示されます。食事の名前をタップすると、ルーティンの上にそのまま別の食事を選んだり時間を変えたりするウィンドウが開きます。何も削除されません。New Meの ⚙️ 設定 → ルーティンの食事 から、またはマイルーティンの⚙️で「New Meと同期」をオフにすると元に戻ります。New Meが有効でなくなると、自動で元に戻ります。",
    faq_a_room_computer: "「今日はここまでどんな一日ですか？」から始まる小さなチャットです。いい・忙しい・つらい のどれかから、一歩ずつ一緒に進んで、最後に小さなミッションをひとつ（そのまま「わたしの一日」に入れることもできます）。答えはタップしても、自由に書いてもOK。書いた内容はいちばん近い答えにつながります。「↩ 戻る」で一歩戻って別の答えを選べ、「新しいチャット」でいつでも最初からやり直せます。忙しい日やつらい日のあとは、同じ日のうちにまたパソコンに戻ってこられます。「戻ってきたよ...」で会話の続きができます。下の緑のランプでパソコンの電源を切ったり入れたりできます。保存されるのは選んだ答えだけで、この端末だけ、その日の終わりまでです。",
    faq_q_ai_chat: "アシスタントとはどうやって話しますか？",
    faq_q_new_me_hall: "New Meの廊下とは何ですか？",
