    faq_a_dictation: "はい。クイックメモやノートの書くページの角にある🎤マイクをタップして話すと、話しながら言葉がアプリの言語で書かれます。もう一度タップすると止まります。初回はブラウザーがマイクの使用許可をたずねます。Chrome / Android と iPhone の Safari で使えます。 パソコンではマイクと、Chrome・Edge・Safari などのブラウザが必要です。足りないものがあれば、メッセージで正確にお知らせします。",
    faq_q_dictation: "入力のかわりに話せますか？",
    faq_a_secret_room: "New Me の中にある、あなただけの部屋。巨大な木の中にある家です。一度に見えるのは壁一面で、矢印（またはスワイプ）で向きを変えます。最初のカギは、3つの別々の日に食事に ✓ するともらえて、扉と部屋全体が開きます：パソコン、ゲーム、レコードプレーヤー、ライブラリーの入った棚、ねこ。そのあとは、チャレンジをひとつ終えるごとに（今週のチャレンジも含みます）カギがもらえ、次の場所が開きます：星の屋上、海の見えるポーチ、ギターと日記、呼吸の部屋、ヨガのある森の小道、滝、屋上のサプライズ。そして8つ目のチャレンジで、過去からの手紙が入ったボトルが海から届きます。何かが開くと、矢印がそこまでの道を示します。ゲーム機の下にある小さな扉も開きます。今のところ、その奥の小さな戸棚は空っぽです。星の屋上では、タップした星が流れ星のように流れ、ねこはクッションに座っています。",
