    room_wall_window_title: "窓とパソコン",
    faq_a_steps_in_sport: "「ワークアウト記録」の一番上にある小さなバーで、今日と今週の歩数が見られます。スマホ版アプリで Google Fit / Apple Health とつながると、歩数は自動で数えられます。横の🔗ボタンで説明が見られます。",
    faq_q_steps_in_sport: "毎日の歩数計はどこにありますか？",
    sport_steps_today_label: "歩（今日）",
    sport_steps_week_label: "歩（今週）",
    faq_a_reminders_one_place: "リマインダーは1回だけ、1か所に届きます。アプリを目の前で開いているとき（パソコン、iPad、スマホ）はそこに表示され、そうでないときはスマホにだけ通知が届きます。どこかで「✅ 完了しました！」か「了解！」をタップすると、すべての端末で閉じて、もう届きません。「まだです」はスヌーズです。5分ごとにまた届き、毎回1か所だけに届きます。リストでタスクに✓を付けても完了になります。パソコンやタブレットにも通知を届けたいときは、設定 > 通知 で「パソコンとタブレットにも」をオンにしてください。",
    faq_q_reminders_one_place: "リマインダーが1回だけ、しかもスマホにだけ届くのはなぜですか？",
    reminder_all_devices_hint: "通常、リマインダーは1回だけ、1か所に届きます。スマホか、アプリを目の前で開いている端末です。1か所で「完了」か「了解」をタップすると、すべての場所で閉じます。",
    reminder_all_devices_label: "パソコンとタブレットにも",
    myday_water_info: "中くらい / 小さめのコップ8杯で、平均約2リットルです",
    faq_a_good_things: "夜（18時以降）、日付の下に小さなボタンが表示されます。今日あったよいことを最大3つ書きましょう。ひとつだけでも十分です。保存され、「これまでの日」で以前に書いたものを見られます。「今夜はやめておく」で明日まで隠せます。設定 > パーソナライズとカレンダー で完全にオフにすることもできます。",
    faq_a_home_countdown: "カレンダーで予定に ⭐ を付けます（予定一覧の横にある星）。今後100日以内でいちばん近い ⭐ 付きの予定が、日付の下に表示されます。「あと3日 · 母の誕生日」「明日 · …」「今日 · …」のように。タップするとカレンダーのその日に移動します。",
    faq_a_home_streak: "少なくとも1つ ✓ があった日が何日続いているかを数えます。わたしの一日、マイルーティン、マイ目標、New Me のどれでもかまいません。2日目から表示されます。今日まだ ✓ がなくても、連続は途切れていません。今日はまだ丸一日あります。途切れたときは静かに消えるだけで、責めるような表示はありません。",
    faq_a_home_weather: "設定 > パーソナライズとカレンダー で「ホーム画面の空に天気を表示」をオンにし、位置情報を許可します。するとホーム画面の空に、いる場所の本当の天気が表示されます – 太陽（夜は月と星）、雲、雨、雪、雷雨、霧 – どのテーマでも表示され、約40分ごとに更新されます。おおよその位置（約1kmに丸めたもの）はお使いの端末にだけ保存され、当社のサーバー経由で MET Norway に問い合わせます。初期設定ではオフです。スイッチの下に、いまの外の天気が表示されます。たとえば ⛅ 晴れ時々くもり のときは、空に太陽と雲の両方が出ます。",
