    faq_a_home_focus: "ホーム画面の上の ◎ をタップすると、いまのひとつのこと – この時間にあること、または今日のリストの次のこと – と大きな ✓、クイックメモ以外はすべて消えます。✓ すると次のことが表示されます。上の「集中モード ✕」ですべて元に戻ります。",
    faq_a_home_search: "メニュー ☰ を開くと、いちばん上に検索があります。2文字以上入力すると、メモ、買い物リスト、カレンダー、レシピ、ノート（タイトルとページの文章）、目標、テーブル、本から結果が種類ごとに表示され、タップするとそこへ直接移動します。",
    faq_a_my_day: "「わたしの一日」は、以前の「今日をチラ見」と「マイルーティン」をひとつのタイムラインにまとめたものです。ホーム画面の下には、できた数といまや次にすること（すぐ ✓ できます）が表示され、タイトルの横では +1 で水を1杯記録できます。タップ（または上にスワイプ）すると一日全体が開きます：上に時間のないもの、続いて時間順にすべて – カレンダーのタスク・予定・会議、毎週の固定枠、今日のルーティン、目標の小さな一歩、New Me の食事 – と「いま」の線。タスク・ルーティン・会議と予定で絞り込めます。ここでの ✓ は他の場所（マイルーティン、マイ目標、カレンダー）と同じ ✓ で、コーナーのデイジーも咲きます。「ルーティンを編集」でマイルーティン（メニューにもあります）が開き、「＋ 今日に追加」で今日のタスクを追加できます。「わたしの一日」のタイトル（または上の小さなバー）をタップすると、また閉じます。",
