    faq_a_table_views: "テーブルの上部で 3 つの表示を切り替えられます。テーブル（横にスクロールしても最初の列は固定され、いちばん下の行で数値の合計と ✓ の数がわかります）、カード（1 行が 1 枚のカード）、ボード（「選択」の列、たとえばステータスごとにカードをまとめた表示。カードを別の列にドラッグすると値が変わります）。列の見出しか ↕ 並べ替えで並べ替え、絞り込みで一部の行だけを表示できます。どちらもテーブルごとに記憶されます。行をタップするとカードとして編集でき、＋ 列ですぐに列を追加できます。⋯ には列の一覧、名前・アイコン・ポケット、テーブルの削除があります。",
