    bag_tasks_general: "📝 一般のタスク",
    faq_a_bag_pockets: "ノート・テーブル・タスクはどれも別のポケットへ移動できます。それぞれの画面を開き（ノートは 🎨、テーブルは ✏️、タスクはタップ）、ポケットを選んでください。ポケットの名前・アイコン・色を変えるには、ポケットを開いて名前の横の ✏️ をタップします。ポケットを削除すると中身もすべて削除されるので、残したいものは先に移動してください。新しいバッグに入っている例も同じように、いつでも変更・削除できます。",
    faq_a_my_bag: "マイバッグには、ノート・テーブル・タスクがまとめて入っています。ポケットは暮らしの分野ごと（家、家族、仕事、旅行など）で、それぞれ名前・アイコン・色があります。ポケットをタップするとバインダーのように開き、中身が 1 ページにまとまって表示されます。横の色付きインデックスで別のポケットへ移動できます。＋ でノート、テーブル（または AI が作るテーブル）、タスク、新しいポケットを追加できます。フィルターでノート・テーブル・タスクだけを表示でき、🔍 ですべてを検索できます。上の ✅ タスクカードは誰でも無料で、ポケット・ノート・テーブルはプレミアムの機能です。",
    faq_q_bag_pockets: "マイバッグの中身を移動・削除するには？",
    faq_q_my_bag: "マイバッグとは？",
    premium_benefit_bag: "マイバッグ – 自分のノートとテーブルが入るポケット",
    faq_a_goal_library: "マイ目標で＋（目標がまだないときはテーマ）をタップすると目標ライブラリーが開きます。健康、体重、音楽、勉強、お金、家族など12のテーマがあり、それぞれ分野ごとに用意されたプランがあります。各プランには週ごとのチェックポイント（または日数チャレンジ、カウント、体重の目標）と毎日の小さな一歩が表示されます。「この目標を始める」ですぐに作成、「先に編集する」で自由に変更でき、「マイルーティンに追加」スイッチで毎日の一歩を空いている時間にルーティンへ入れられます（時間をタップすると別の時間を選べます） – 片方で✓するともう片方にも✓が付きます。検索（「ギター」「試験」）もでき、「✏️ 自分の目標」もいつでも選べます。各テーマ2件のプランは無料、ライブラリーのすべてはプレミアムで使えます ⭐。",
    faq_q_goal_library: "目標ライブラリーとは？用意されたプランから目標を始めるには？",
