    faq_a_new_me_letter_gift: "New Meの始めに（またはあとでチャレンジ画面から）、未来の自分への手紙を書けます。封をすると、開くまで読むことも編集することもできません。手紙が開くのは、ひみつの部屋にある海からのボトルの中か、20のチャレンジをすべて終えたときです（そのときにはギフトも待っています）。",
    faq_q_new_me_letter_gift: "過去からの手紙とは？",
    faq_a_new_me_challenges: "🏆 チャレンジには20のチャレンジがあります：ビッグ10個（砂糖なしの5日間、炭水化物なしの1週間、1か月で4 kg減 – 毎日カロリー赤字・ワークアウト・砂糖なし、など）と、ミニ10個 – 砂糖なしのシナモンコーヒーのような1週間の小さな習慣。チャレンジを選ぶと、いつ始めるか（今日、明日、来週、別の日）を聞かれます。ビッグとミニは同時に進められます。進行中のチャレンジはメニューの一番上と「わたしの一日」に表示され、その日の ✓ を付けられます。チャレンジ1週間ごとに、チャレンジが途切れないフリーデー（🍕）が1日あり、チェックしなかった日はフリーデーとして数えられます – 今日と昨日はチェックできます。自動でチェックされる日もあります：ワークアウト記録での20分の運動や、✓ が付いたメニューの食事。各チャレンジには、何がカウントされるかが正確にわかる ⓘ があります（例：炭水化物の全リスト）。チャレンジの中と、「わたしの一日」のチャレンジの横にあります。その下の 🌱 自己成長には、1週間の小さなチャレンジが48個あります（この20個には数えません）。「今週のチャレンジとは？」をご覧ください。",
