    nm_tile_challenges: "チャレンジ",
    faq_a_workout_calories: "はい。運動ごとに消費カロリーの推定値が計算されます – 種類、時間、最新の体重から（ランニングとサイクリングは距離を入れると速度も考慮）。運動の一覧と月間サマリー（消費）に表示され、その日のカロリー予算に加わります：毎日の食事記録、カロリーと体重の指標、New Meのリングに反映されます。推定値なので「~」付きで表示されます。",
    faq_q_workout_calories: "運動は1日のカロリーに反映されますか？",
    faq_a_new_me_flexible_menu: "はい。質問票と設定で1日の食事の数（食事2回 + 間食 / 食事2回 + 軽い夕食 / 食事2回 + 間食 + 軽い夕食）を選べます。食事カードの➖で外すこともできます（最低3つは残ります）。「献立に戻す」で戻せます。どの場合も1日のカロリーは変わらず、外した分はほかの食事に分けられ、各食事の下にどれだけ増えたか、何を足せるかが表示されます。✏️編集を押すと食事の文章が開き、好きなように変えると（例：パンなし、卵をもう1つ）AIがカロリーとたんぱく質を計算し直します。🔄入れ替えでは献立の選択肢、⭐保存済み、✨書いて選ぶが使え、どの変更も今日だけか今後ずっとかを選べます。「1日全体」の最後には➕食べ物を追加があり、献立以外に食べたものを書くとAIが計算して今日に足します（✕で削除）。",
