    faq_a_app_tour: "ツアーは最初にアプリに入ったとき、一度だけ自動で開きます。まずツアーのパートが表示され、タップするとそのパートへ直接移動できます。続いてアプリのすべての部分（ホーム画面、AIアシスタント、メニューの各項目）と設定の5つのグループを短い説明つきで紹介し、いくつかは中まで見せます（例：目標の道のりの見本、バッグ、Google Calendar）。「次へ」で進み、「戻る」で戻り、「このパートをスキップ」で次のパートへ、✕でツアーを閉じます。設定 > ヘルプと使い方 > アプリツアー からいつでも見直せて、前回の続きから再開できます。 「次へ」と「戻る」はいつも画面下の同じ場所にあり、パソコンではキーボードの矢印キーも使えます。",
