    apptour_m_newme_link: "すべて「毎日の食事記録」と「わたしの一日」に反映され、体重は「カロリーと体重の指標」と共有されます。",
    apptour_m_newme_text: "魔法のゲームの世界で進む1,300 / 1,500カロリーの食事プラン：✓ 付きの今日の献立、3つの方法での入れ替え – 献立から、保存済みの食事から、または食べたものをAIに書けばカロリーを計算 – 買い物リスト、食事リマインダー、そしてバッジ・サイズ測定・写真で進歩をたどる歩みの記録。さらに 🏆 20のチャレンジ – 最後にはギフトも – と今週のチャレンジ。",
    apptour_ai_table_text: "必要なテーブルを説明すると、AIが列を設計します（プレミアム）。",
