    apptour_ai_text: "かんたんな言葉で書くだけで、アシスタントが残りをやってくれます：カロリーの記録、予定をカレンダーへ、写真からレシピの読み取り、表づくり。",
    apptour_quicknote_link: "📝 と 🛒 で各リストの全体を開き、🍎 で保存済みの食事を「毎日の食事記録」に記録します。",
    apptour_quicknote_text: "さっと書き留めて、「メモ」に保存するか、そのまま「買い物リスト」へ。",
