    faq_a_other_manual_option: "選択肢のリストから選ぶ場所には、どこでも「✏️ その他」があります。それを選んで、必要な内容をそのまま入力してください。選択列のあるテーブル(例：プレゼント表の「続柄」)では、セルをタップして「✏️ その他」を選び、値(例：「甥」)を入力して追加をタップします。その列の新しい選択肢として保存されるので、次回からはリストに表示されます。そのリストの各選択肢の横にある小さな×をタップすると、その選択肢が列から削除されます。テーブルのアイコンを選ぶときは、たくさんのアイコン(カラフルな付箋を含む)から選べます。保存済みの食事のカテゴリー、レシピのカテゴリー、定期支出のカテゴリー(新しい個人カテゴリーとして保存)、マイ目標のカテゴリーでも同じように使えます。",
