    faq_a_receipts_total: "請求書・領収書の画面で 🧮「全領収書の合計」をタップします。開始年と終了年を選び（初期値は最も古い領収書の年から今年まで）、「計算」をタップすると、両カテゴリー（家庭の支出と事業の支出）を合わせた合計に加えて、領収書の件数と各カテゴリーごとの合計が表示されます。",
