    nm_extras_hint: "毎日の食事記録とクイック追加から – リングにすでに反映済み。",
    nm_extras_title: "今日ほかに食べたもの",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "飲み物の名前とカロリーを入力してください",
    nm_drink_more: "+ 飲み物を追加",
    nm_drink_add: "追加",
    nm_drink_name_ph: "飲み物（例：ジュース）",
    nm_drinks_hint: "飲み物の名前を入力するだけで、カロリーが自動で計算されます（数値は変更できます）。",
    nm_slot_drinks: "飲み物",
    faq_a_new_me_tracking: "New Meの上にある次のミッションをタップして、✓ 食べたをタップすると、次の食事を食べたことを記録できます。全食事に✓がついた献立は、横にある「1日全体」にあり、今日の食事はホーム画面の「わたしの一日」にも表示されます。そこで食事をタップする（またはマウスを重ねる）と、何を食べればいいかが具体的に表示され、✓と「入れ替え」も使えます。すべて毎日の食事記録と同期しています。プランの食事、飲み物、ほかの場所で追加したもの（たとえばクイック追加のコーヒー）は、New Meと「わたしの一日」でまとめて数えられます。すでに入力したものは上書きされず、✓を外すとNew Meの分だけが消えます。今日の食事がすべてチェックされると、小さなお祝いがあります。「飲み物」には1日の飲み物を記録します。合計で~150 kcalまで、つまり~50 kcalまでの飲み物が3杯ほどです。飲み物の名前を入れるだけで、カロリーがAIで自動入力されます。コーヒー／紅茶の2行には「ミルクは？量は？」の欄もあり（例：「少し」「50 ml」）、計算が更新されます。数値は追加前にもあとにも変更できます。名前とカロリーのある飲み物は、次に進んだ時点で自動保存されるので、「追加」のタップは任意です。飲み物の横の☆をタップするといつもの飲み物として保存され、飲み物カードの上にボタンとして表示されて、ワンタップで追加できます。⭐は食事を保存済みの食事として保存します。「1日の表」には食べたものがカロリーとたんぱく質つきで表示されます。ホーム画面の上、集中モードの横にある小さな💎でNew Meを直接開けます。カロリーとたんぱく質の値はAIによる推定で、誤りが含まれる場合があります。 全部は食べなかった？ チェック済みの食事の下にある「全部は食べなかった？」で、量の4分の1・半分・4分の3、または書いた内容を計算して差し引くと、1日のカロリーが更新されます。",
    faq_q_new_me_tracking: "New Meの✓、入れ替え、カロリーはどう機能しますか？",
    faq_a_new_me_what: "New Meは独立した毎日の献立プログラムで、2つの既製プラン（1,300または1,500kcal）は、主食事2回と間食2回で構成され、それぞれ3つの選択肢があります。プレミアムの機能もすべて含まれます。料金は月額$11.99（いつでも解約可能）または$99.99の買い切りです。メニューの💎 New Meから開きます。開始前に短い質問票があり、最初に同意が必要な医療に関する免責事項が表示されます。このプログラムは一般的な情報であり、医師や臨床栄養士の代わりにはなりません。",
    faq_q_new_me_what: "New Meとは何ですか？どうすれば入手できますか？",
