    food_estimate_local_db_reasoning: "AIの推測ではなく、食品データベースで見つかりました。意図した食品でない場合は「違います」をタップしてください。",
    food_clarify_milk_question: "{ingredient}は飲み物に混ぜる牛乳の代わりですか？それとも別の固形の食べ物ですか？量も入力してください。",
    food_ai_fallback_toast: "現在、AIによる詳細な推定に接続できないため、簡易的なおおよその推定を表示しています。カロリーは手動で編集するか、少し後にもう一度記録してください。",
