    daily_focus_p1_d5_s1: "自分の心の空間を、清らかで守られたものに保つ", daily_focus_p1_d5_s2: "自分の内側に、安らぎと深い静けさを感じる", daily_focus_p1_d5_s3: "自分を受け入れながら、着実な前進を選ぶ", daily_focus_p1_d5_s4: "穏やかな気持ちで、心を落ち着けてやるべきことを終える", daily_focus_p1_d5_s5: "自分自身と、うまく乗り越える力を信じる",
    daily_focus_p1_d6_s1: "自分の自己価値を、揺るぎなく強く保つ", daily_focus_p1_d6_s2: "今この瞬間に意識を向け、その時間を楽しむ", daily_focus_p1_d6_s3: "忍耐強くあり続け、自分のプロセスを心から信じる", daily_focus_p1_d6_s4: "行動すべき時と、そっと手放すべき時を見極める", daily_focus_p1_d6_s5: "すべてのことに対して、健全で良いバランス感覚を取り戻す",
    daily_focus_p1_d7_s1: "深く心地よい休息のために、敬意を持って場所を空ける", daily_focus_p1_d7_s2: "内なる静けさに耳を傾け、体をゆるめる", daily_focus_p1_d7_s3: "自分の周りを、優しい言葉と心地よい思いで満たす", daily_focus_p1_d7_s4: "すべてのやるべきことを手放し、質の良い時間に身をゆだねる", daily_focus_p1_d7_s5: "これまでの道のりへの感謝で、心を満たす",
    daily_focus_p2_d1_s1: "気が散る要素のない、静かな作業スペースを保つ", daily_focus_p2_d1_s2: "今日必要なことに耳を傾け、一番大事なことを優先する", daily_focus_p2_d1_s3: "行動を後押しする前向きな自分との対話を選ぶ", daily_focus_p2_d1_s4: "メインのタスクからまっすぐ始めて勢いをつける", daily_focus_p2_d1_s5: "決意と成功へのマインドセットで一日を開く",
    daily_focus_p2_d2_s1: "自分のスケジュールに集中し、時間を一番大事なことに使う", daily_focus_p2_d2_s2: "明確でシャープな決断からまっすぐ行動する", daily_focus_p2_d2_s3: "変化に柔軟に対応し、すぐに軌道に戻る", daily_focus_p2_d2_s4: "タスクに一貫して取り組み、強い自制心を築く", daily_focus_p2_d2_s5: "約束を守るために注いだ努力を認める",
    daily_focus_p2_d3_s1: "自分の目標とのつながりを保ち、集中を深める", daily_focus_p2_d3_s2: "スピードを落として、最大限の正確さと質で取り組む", daily_focus_p2_d3_s3: "すべての会話と調整で完全な明瞭さを保つ", daily_focus_p2_d3_s4: "一つのことに集中し、完全に終わらせるまでやり抜く", daily_focus_p2_d3_s5: "どんな困難からもすぐに学びを得て、前へ進み続ける",
    daily_focus_p2_d4_s1: "高いエネルギーを生む、正確な作業ペースを保つ", daily_focus_p2_d4_s2: "意識的に休憩を取り、集中力を研ぎ澄ます", daily_focus_p2_d4_s3: "自分の仕事の計画を信じて、それを貫く", daily_focus_p2_d4_s4: "大きなタスクをシンプルで整理された手順に分ける", daily_focus_p2_d4_s5: "ここ数日で積み重ねた素晴らしい進歩を認める",
    daily_focus_p2_d5_s1: "自分の高い基準と実行の質を保つ", daily_focus_p2_d5_s2: "自分を前進させる実践的な行動で頭を満たす", daily_focus_p2_d5_s3: "シンプルさと流れの中でタスクを終わらせることを選ぶ", daily_focus_p2_d5_s4: "未処理のことを片付け、すっきりした頭でタスクを終える", daily_focus_p2_d5_s5: "どんどん強くなっている自分の自制心を信じる",
    daily_focus_p2_d6_s1: "仕事と余暇の正しいバランスを保つ", daily_focus_p2_d6_s2: "この数日を丁寧に振り返り、学びを引き出す", daily_focus_p2_d6_s3: "一歩ずつ積み上げていくプロセスに辛抱強く向き合う", daily_focus_p2_d6_s4: "成し遂げたすべてを認め、穏やかに力を抜く", daily_focus_p2_d6_s5: "発揮してきた自制心に満足感を覚える",
    daily_focus_p2_d7_s1: "この日を、充電と完全なリフレッシュのために使う", daily_focus_p2_d7_s2: "内なる望みに耳を傾け、自分を満たすことをする", daily_focus_p2_d7_s3: "自分の粘り強さとここまでの道のりを心から労う", daily_focus_p2_d7_s4: "すべての計画を手放し、心の自由を楽しむ", daily_focus_p2_d7_s5: "粘り強く続け、学び、成長できる力に感謝する",
    faq_q_daily_focus_prompt: "今日いちばん大事なことを聞いてくる小さなリマインダーは何ですか？", faq_a_daily_focus_prompt: "Premiumの毎日のリマインダーです。1日に1回、AIアシスタントのアイコンに小さな「1」のバッジが表示されます。バッジをタップすると、今日いちばん大事なことを尋ねる吹き出しが開き、すぐに5つの提案(毎日入れ替わり、1年分のさまざまなテーマを順番にめぐるので新鮮さが続きます)と、自分で書ける「その他」が表示されます。複数選ぶこともできます。追加をタップすると、選んだものが「わたしの一日」の上部に小さなリマインダータグとして表示されます(チェックするタスクではありません)。✕で閉じたり外側をタップしたりすると、バッジは消えずに、その日の残りの間は薄く表示されます。初期設定ではオンですが、設定 > パーソナライズとカレンダーでオフにできます。今日は気分じゃないときは「🌙 今日はパス」をタップ。バッジは明日まで消え、明日にはいつもどおり質問が戻ります。提案のひとつは、あなた自身のデータから選ばれます（今月の目標の次のステップや、今日の読書など）。毎日、まっさらな状態から始まります。",
