    auth_forgot_password_link: "パスワードをお忘れですか？", auth_back_to_login: "ログインに戻る", auth_forgot_subtitle: "メールアドレスを入力すると、リセットリンクをお送りします：", auth_forgot_submit_btn: "リセットリンクを送信", auth_fill_email: "メールアドレスを入力してください", auth_forgot_success: "そのメールアドレスが存在する場合、リセットリンクが届きます - 受信箱を確認してください。",
